{
  "decision-shield-bias-from-probe-swap": "WITH ranked AS (SELECT run_id, proto_probe, slip_id, p_tenth, q_tenth, ROW_NUMBER() OVER (PARTITION BY run_id, proto_probe ORDER BY slip_id COLLATE BINARY) AS rn FROM bench_slip WHERE p_tenth IS NOT NULL AND q_tenth IS NOT NULL) SELECT p.run_id, 5 * ((p.p_tenth - p.q_tenth) + (q.q_tenth - q.p_tenth)) AS effect_centi_c, p.slip_id AS p_proto_slip, q.slip_id AS q_proto_slip FROM ranked AS p JOIN ranked AS q ON q.run_id = p.run_id WHERE p.proto_probe = 'P' AND q.proto_probe = 'Q' AND p.rn = 1 AND q.rn = 1 ORDER BY p.run_id ASC",
  "decision-shift-standardized-turnover": "WITH totals AS (SELECT site_code, shift_code, SUM(departures) AS dep, SUM(exposure) AS exp FROM shift_counts GROUP BY site_code, shift_code HAVING SUM(exposure) > 0) SELECT d.site_code, (1000 * (d.dep * n.exp + n.dep * d.exp) + d.exp * n.exp) / (2 * d.exp * n.exp) AS standardized_per_1000 FROM totals AS d JOIN totals AS n ON n.site_code = d.site_code WHERE d.shift_code = 'day' AND n.shift_code = 'night' ORDER BY standardized_per_1000 DESC, d.site_code ASC",
  "decision-simultaneous-terminal-bay-outages": "WITH RECURSIVE minutes(terminal_id, minute, end_min) AS (SELECT terminal_id, start_min, end_min FROM terminal_watch WHERE start_min < end_min UNION ALL SELECT terminal_id, minute + 1, end_min FROM minutes WHERE minute + 1 < end_min), blocked AS (SELECT m.terminal_id, COUNT(*) AS blocked_minutes FROM minutes AS m WHERE (SELECT COUNT(DISTINCT o.bay_code) FROM bay_outage AS o WHERE o.terminal_id = m.terminal_id AND o.failed_min <= m.minute AND m.minute < COALESCE(o.restored_min, m.end_min)) = 2 GROUP BY m.terminal_id) SELECT w.terminal_id, COALESCE(b.blocked_minutes, 0) AS blocked_minutes FROM terminal_watch AS w LEFT JOIN blocked AS b ON b.terminal_id = w.terminal_id ORDER BY w.terminal_id ASC",
  "decision-single-feed-finals-handoff": "SELECT c.slot_id AS copper_slot, j.slot_id AS jade_slot, (c.end_min - c.start_min) * c.viewers + (j.end_min - j.start_min) * j.viewers AS viewer_minutes FROM air_slot AS c CROSS JOIN air_slot AS j WHERE c.division = 'Copper' AND j.division = 'Jade' AND MAX(j.start_min - c.end_min, c.start_min - j.end_min) >= CASE WHEN c.hall = j.hall THEN 5 ELSE 15 END ORDER BY viewer_minutes DESC, c.slot_id COLLATE BINARY ASC, j.slot_id COLLATE BINARY ASC LIMIT 1"
}
